const task = $('Supabase Webhook').item.json.body.record;
const employee = $input.item.json;

// Format checklist if it exists
let checklistHtml = '';
if (task.checklist && Array.isArray(task.checklist) && task.checklist.length > 0) {
  checklistHtml = '<h3>Checklist:</h3><ul>';
  task.checklist.forEach(item => {
    let text = typeof item === 'string' ? item : (item.text || item.step || JSON.stringify(item));
    checklistHtml += `<li>${text}</li>`;
  });
  checklistHtml += '</ul>';
}

// Format Deadline
let deadline = task.deadline || 'No specific deadline';

const emailHtml = `
  <div style="font-family: Arial, sans-serif; padding: 20px; color: #333;">
    <h2>Hello ${employee.name},</h2>
    <p>A new task has been assigned to you.</p>

    <div style="background-color: #f4f6f9; padding: 15px; border-left: 4px solid #0ea5e9; margin: 20px 0;">
      <h3 style="margin-top: 0;">Task Details</h3>
      <p><strong>Description:</strong> ${task.description}</p>
      <p><strong>Deadline:</strong> ${deadline}</p>
      <p><strong>Source:</strong> ${task.source || 'Direct Assignment'}</p>
      <p><strong>Priority:</strong> ${task.priority || 'Normal'}</p>
    </div>

    ${checklistHtml}

    <p>Please check your Task Updater app for more details.</p>
    <br/>
    <p>Best regards,<br/>Stauff Orchestration System</p>
  </div>
`;

return {
  json: {
    recipientEmail: employee.email,
    subject: `New Task Assigned: ${task.description.substring(0, 50)}...`,
    emailBody: emailHtml
  }
};
